static bool Balanced(string s)
{
    Stack<char> st = new Stack<char>();
    foreach (char c in s)
    {
        if (c == '(' || c == '[' || c == '{') { st.Push(c); }
        else if (c == ')' || c == ']' || c == '}')
        {
            if (st.Count == 0) { return false; }
            char open = st.Pop();
            if ((c == ')' && open != '(') || (c == ']' && open != '[') || (c == '}' && open != '{')) { return false; }
        }
    }
    return st.Count == 0;
}

